// Package math contains set of basic math functions to be able to perform simple arithmetic operations
package math

// AddInt -
func AddInt(n ...int64) int64 {
	x := int64(0)
	for _, i := range n {
		x += i
	}
	return x
}

// MulInt -
func MulInt(n ...int64) int64 {
	var x int64 = 1
	for _, i := range n {
		x *= i
	}
	return x
}

// Seq - return a sequence from `start` to `end`, in steps of `step`.
func Seq(start, end, step int64) []int64 {
	// a step of 0 just returns an empty sequence
	if step == 0 {
		return []int64{}
	}

	// handle cases where step has wrong sign
	if end < start && step > 0 {
		step = -step
	}
	if end > start && step < 0 {
		step = -step
	}

	// adjust the end so it aligns exactly (avoids infinite loop!)
	end -= (end - start) % step

	seq := []int64{start}
	last := start
	for last != end {
		last = seq[len(seq)-1] + step
		seq = append(seq, last)
	}
	return seq
}

// Package net contains functions to help with network-oriented lookups
package net

import (
	"context"
	"net"
	"slices"
)

// LookupIP -
func LookupIP(ctx context.Context, name string) (string, error) {
	i, err := LookupIPs(ctx, name)
	if err != nil {
		return "", err
	}
	if len(i) == 0 {
		return "", nil
	}
	return i[0], nil
}

// LookupIPs -
func LookupIPs(ctx context.Context, name string) ([]string, error) {
	resolver := &net.Resolver{}
	srcIPs, err := resolver.LookupIPAddr(ctx, name)
	if err != nil {
		return nil, err
	}

	// perf note: this slice is not really worth pre-allocating - srcIPs tends
	// to be very small, and LookupIPAddr is relatively expensive
	var ips []string
	for _, v := range srcIPs {
		if v.IP.To4() != nil {
			s := v.IP.String()
			if !slices.Contains(ips, s) {
				ips = append(ips, s)
			}
		}
	}
	return ips, nil
}

// LookupCNAME -
